#!/bin/sh
# Subtitld's projects (.usfx) as a file type of their own: a description,
# the extension, Subtitld to open them, and their icon (usfx.hvif).
# Run once the package is installed (POST_INSTALL_SCRIPTS in the recipe).
# Generated by packaging/branding/render-icons.py; do not edit.
#
# The package already carries the type, read-only, with only Subtitld as its
# preferred app (data/mime_db, from the file types the app declares), so
# -add lays the rest over it in the user's MIME database (as on a
# reinstall); -force would try to replace the read-only entry and fail.
# -set if the type is not there at all. The sniffer rule: a zip whose first
# entry is Subtitld's, above the zip's own rule (0.40), which would
# otherwise win over the extension.
if setmime -dump application/x-usfx > /dev/null 2>&1; then mode=-add; else mode=-set; fi
setmime $mode application/x-usfx \
	-short "Subtitld project" \
	-long "Subtitld project: subtitles, speakers and dubs" \
	-extension usfx \
	-sniffRule '0.60 ("PK\003\004") [30] ("subtitles.usf" | "manifest.xml")' \
	-preferredAppSig application/x-vnd.qt6-Subtitld \
	-vectorIcon 
